package net.civeira.phylax.feature.notification.message.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.message.domain.Message;
import net.civeira.phylax.feature.notification.message.domain.valueobject.UrgentVO;

class UrgentValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of urgent of message")
  void test_urgent_value_holder_assign_plain_value() {
    Object holder = new Object();
    UrgentValueHolder<Object> value = new UrgentValueHolder<>(holder);
    Assertions.assertSame(holder, value.urgent(true), "Setters must return the holder");
    Assertions.assertTrue(value.getUrgentValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getUrgent().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of urgent of message")
  void test_urgent_value_holder_assign_value_object() {
    Object holder = new Object();
    UrgentValueHolder<Object> value = new UrgentValueHolder<>(holder);
    UrgentVO vo = UrgentVO.from(true);
    Assertions.assertFalse(value.getUrgentValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.urgent(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getUrgentValue().orElseThrow());
    Assertions.assertSame(holder, value.urgent(Optional.empty()));
    Assertions.assertFalse(value.getUrgentValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.urgent(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUrgentValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of urgent of message against the original")
  void test_urgent_value_holder_read() {
    Object holder = new Object();
    UrgentValueHolder<Object> value = new UrgentValueHolder<>(holder);
    UrgentVO vo = UrgentVO.from(true);
    UrgentVO other = UrgentVO.from(true);
    Message original = Mockito.mock(Message.class);
    Mockito.when(original.getUrgentValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUrgent(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readUrgent(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.urgent(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUrgent(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUrgent(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of urgent of message")
  void test_urgent_value_holder_unset() {
    Object holder = new Object();
    UrgentValueHolder<Object> value = new UrgentValueHolder<>(holder);
    UrgentVO vo = UrgentVO.from(true);
    value.urgent(vo);
    Assertions.assertSame(holder, value.unsetUrgentIfMatches("urgent_other"));
    Assertions.assertTrue(value.getUrgentValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetUrgentIfMatches("urgent"));
    Assertions.assertFalse(value.getUrgentValue().isPresent(),
        "The field name must clear the value");
    value.urgent(vo);
    Assertions.assertSame(holder, value.unsetUrgent());
    Assertions.assertFalse(value.getUrgentValue().isPresent(), "Unset must clear the value");
  }
}
